import { HuntingEvidenceGraph } from "@/components/hunting-evidence-graph"
import { AssistantAnswer } from "@/components/assistant-answer"
import { useEffect, useMemo, useRef, useState } from "react"
import { Activity, ChevronRight, Clock3, Download, FileSearch, Bot, Search, SlidersHorizontal, X, Maximize2 } from "lucide-react"
import { api } from "@/lib/api"
import { Button } from "@/components/ui/button"
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet"

type Source = { source: string; rows: number; sha256?: string; bytes?: number; status?: string; completeness?: string }
type ImportRow = { id: string; sha256: string; size: number; created_at: string; summary: { total_rows: number; sources: Source[]; collection_provenance?: { claims_verified: boolean; capture_started_utc_claim?: string | null; requested_sources: { id: string; configured_row_limit: number; observed_rows: number; status: string; limit_reached: boolean }[] } } }
type FindingReview = { status: "needs_review" | "confirmed" | "benign" | "insufficient_evidence"; note: string; updated_at?: string }
type Finding = { evidence_refs?: { source: string; row_number: number; relation: string }[]; benign_explanations?: string[]; data_gaps?: string[]; assessment?: string; rule_id: string; title: string; reason: string; source: string; row_offset: number; row_number: number; classification: string; triage_level?: string; confidence?: number; risk_score?: number; recommended_checks?: string[]; evidence?: Record<string, unknown> | null; review?: FindingReview | null }
type Analysis = { graph?: { nodes: { id: string; kind: string; label: string; evidence_refs?: { source: string; row_number: number }[] }[]; edges: { source: string; target: string; relation: string; confidence: string }[]; truncated: boolean }; iocs?: { type: string; value: string; evidence_refs: { source: string; row_number: number; field: string }[] }[]; source_coverage?: { source: string; rows: number; supported: boolean }[]; import_id: string; ruleset: string; verdict: string; matched_rules: number; truncated: boolean; rows_reviewed: Record<string, number>; missing_sources: string[]; empty_sources: string[]; unsupported_sources: string[]; limitations: string[]; findings: Finding[]; triage_summary?: { max_risk_score?: number; correlations?: { process_network: number; process_persistence?: number }; timeline_truncated?: boolean; timeline?: { timestamp: string; source: string; row_number: number; category?: string }[] } }
type PipelineEvent = { stage: string; percent: number; message: string; created_at: string }
type Pipeline = { id: string; result_id?: string | null; stage: string; percent: number; status: string; message: string; rows_processed: number; findings_count: number; error_message?: string | null; events: PipelineEvent[] }
type Page = { rows: Record<string, unknown>[]; total: number; offset: number; limit: number; source: string }
type Tab = "overview" | "findings" | "activity" | "graph" | "evidence" | "ai" | "manual"

const sourceLabel = (source: string) => { let decoded = source; try { decoded = decodeURIComponent(source) } catch { /* untrusted source path */ } const match = decoded.match(/^results\/(?:BroSec\.Offline\.Baseline\/)?(.+?)\.json$/); return match ? match[1].replace("/Analysis", "") : decoded.split("/").pop() || decoded }
const findingLevel = (finding: Finding) => (finding.triage_level || finding.classification || "unknown").toLowerCase()
const levelClass = (level: string) => level === "critical" || level === "high" ? "border-red-500/30 bg-red-500/10 text-red-700 dark:text-red-300" : level === "medium" ? "border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-300" : "border-blue-500/30 bg-blue-500/10 text-blue-700 dark:text-blue-300"
const errorMessage = (error: unknown, fallback: string) => error instanceof Error ? error.message : fallback

// A path, a public IP, or a snapshot PID match is context, not a detection.
const behavioralRules = new Set([
  "process.encoded_powershell", "process.suspicious_invocation",
  "persistence.service_suspicious_invocation", "persistence.task_suspicious_invocation", "persistence.startup_suspicious_invocation",
])
function suspiciousFinding(finding: Finding, all: Finding[]): boolean {
  if (finding.review?.status === "benign") return false
  if (finding.review?.status === "confirmed") return true
  if (behavioralRules.has(finding.rule_id)) return true
  if (finding.rule_id === "process.anomalous_parent_child") return finding.classification === "review"
  if (!["correlation.process_network", "correlation.process_persistence"].includes(finding.rule_id)) return false
  return (finding.evidence_refs || []).some(ref => all.some(other =>
    other.source === ref.source && other.row_number === ref.row_number &&
    behavioralRules.has(other.rule_id) && other.review?.status !== "benign"))
}
function compareFindings(a: Finding, b: Finding) {
  return (b.risk_score ?? -1) - (a.risk_score ?? -1) || a.source.localeCompare(b.source) || a.row_number - b.row_number || a.rule_id.localeCompare(b.rule_id)
}

type ForensicResult = { result: ImportRow; analysis: Analysis; pipeline: Pipeline | null }

export function HuntingResults({ companyId, revision, resultId, historyOnly = false, onOpenResult, onDeleted }: { companyId: number; revision: number; resultId?: string; historyOnly?: boolean; onOpenResult?: (id: string) => void; onDeleted?: () => void }) {
  const [history, setHistory] = useState<{ total: number; items: ImportRow[] }>({ total: 0, items: [] })
  const [offset, setOffset] = useState(0)
  const [selected, setSelected] = useState<ImportRow | null>(null)
  const [analysis, setAnalysis] = useState<Analysis | null>(null)
  const [pipeline, setPipeline] = useState<Pipeline | null>(null)
  const [error, setError] = useState("")
  const [busy, setBusy] = useState(false)
  const [historyLoading, setHistoryLoading] = useState(false)
  const [refresh, setRefresh] = useState(0)
  const [deleting, setDeleting] = useState<string | null>(null)
  const [evidence, setEvidence] = useState<{ page: Page; source: string; offset: number } | null>(null)
  const requestVersion = useRef(0)

  useEffect(() => {
    if (resultId) return
    const controller = new AbortController()
    setHistoryLoading(true); setError("")
    void api<{ total: number; items: ImportRow[] }>(`/api/threat-hunting/results?company_id=${companyId}&offset=${offset}&limit=10`, { signal: controller.signal }).then(next => {
      if (controller.signal.aborted) return
      if (offset > 0 && !next.items.length) { setOffset(Math.max(0, offset - 10)); return }
      setHistory(next)
    }).catch(e => { if (!controller.signal.aborted) setError(errorMessage(e, "Не удалось загрузить архивы")) }).finally(() => { if (!controller.signal.aborted) setHistoryLoading(false) })
    return () => controller.abort()
  }, [companyId, offset, revision, resultId, refresh])

  useEffect(() => {
    const controller = new AbortController()
    const version = ++requestVersion.current
    setSelected(null); setAnalysis(null); setPipeline(null); setEvidence(null); setError("")
    if (!resultId) { setBusy(false); return () => controller.abort() }
    setBusy(true)
    void api<ForensicResult>(`/api/threat-hunting/results/${encodeURIComponent(resultId)}/forensic?company_id=${companyId}`, { signal: controller.signal }).then(full => {
      if (!controller.signal.aborted && version === requestVersion.current) { setSelected(full.result); setAnalysis(full.analysis); setPipeline(full.pipeline) }
    }).catch(e => { if (!controller.signal.aborted && version === requestVersion.current) setError(errorMessage(e, "Расследование недоступно")) }).finally(() => { if (!controller.signal.aborted && version === requestVersion.current) setBusy(false) })
    return () => { controller.abort(); if (version === requestVersion.current) requestVersion.current++ }
  }, [companyId, resultId, revision, refresh])

  const pipelineId = pipeline?.id
  const pipelineStatus = pipeline?.status
  useEffect(() => {
    if (!pipelineId || pipelineStatus === "completed" || pipelineStatus === "failed") return
    const controller = new AbortController()
    let active = false
    const timer = window.setInterval(() => {
      if (active) return
      active = true
      void api<Pipeline>(`/api/threat-hunting/pipeline/jobs/${encodeURIComponent(pipelineId)}?company_id=${companyId}`, { signal: controller.signal }).then(next => { if (!controller.signal.aborted) setPipeline(current => current?.id === next.id ? next : current) }).catch(e => { if (!controller.signal.aborted) setError(errorMessage(e, "Не удалось обновить прогресс")) }).finally(() => { active = false })
    }, 1500)
    return () => { controller.abort(); window.clearInterval(timer) }
  }, [companyId, pipelineId, pipelineStatus])

  async function remove(item: ImportRow) {
    if (deleting || !window.confirm(`Удалить архив от ${new Date(item.created_at).toLocaleString("ru-RU")} и связанные результаты расследования? Это действие нельзя отменить.`)) return
    setDeleting(item.id); setError("")
    try {
      await api(`/api/threat-hunting/results/${encodeURIComponent(item.id)}?company_id=${companyId}`, { method: "DELETE" })
      if (selected?.id === item.id) { requestVersion.current++; setSelected(null); setAnalysis(null); setPipeline(null); setEvidence(null) }
      setHistory(current => ({ total: Math.max(0, current.total - 1), items: current.items.filter(row => row.id !== item.id) }))
      setRefresh(value => value + 1); onDeleted?.()
    } catch (e) { setError(errorMessage(e, "Не удалось удалить архив")) }
    finally { setDeleting(null) }
  }
  async function analyze() {
    if (!selected) return
    const version = ++requestVersion.current
    setBusy(true); setError("")
    try { const next = await api<Analysis>(`/api/threat-hunting/results/${encodeURIComponent(selected.id)}/analysis?company_id=${companyId}`, { method: "POST" }); if (version === requestVersion.current) setAnalysis(next) }
    catch (e) { if (version === requestVersion.current) setError(errorMessage(e, "Анализ не выполнен")) }
    finally { if (version === requestVersion.current) setBusy(false) }
  }
  async function exportResult(format: "xlsx" | "pdf") {
    if (!selected) return
    const version = requestVersion.current
    try {
      const response = await fetch(`/api/threat-hunting/results/${encodeURIComponent(selected.id)}/export/${format}?company_id=${companyId}`, { credentials: "same-origin" })
      if (!response.ok) throw new Error("Экспорт не выполнен")
      const url = URL.createObjectURL(await response.blob())
      const link = document.createElement("a"); link.href = url; link.download = `${selected.id}-forensic.${format}`; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000)
    } catch (e) { if (version === requestVersion.current) setError(errorMessage(e, "Экспорт не выполнен")) }
  }
  async function openEvidence(finding: Finding, nextOffset = finding.row_offset) {
    if (!selected) return
    const version = requestVersion.current
    try {
      const page = await api<Page>(`/api/threat-hunting/results/${encodeURIComponent(selected.id)}/rows?company_id=${companyId}&source=${encodeURIComponent(finding.source)}&offset=${nextOffset}&limit=25`)
      if (version === requestVersion.current) setEvidence({ page, source: finding.source, offset: nextOffset })
    } catch (e) { if (version === requestVersion.current) setError(errorMessage(e, "Evidence недоступен")) }
  }
  return <section className="space-y-4" aria-busy={busy || historyLoading}>
    <header className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-semibold">{resultId ? "Расследование архива" : "История импортов и расследований"}</h2><p className="text-sm text-muted-foreground">{resultId ? "Исходные данные, находки и решения аналитика." : `${history.total} архивов в выбранной компании. Откройте архив для анализа выше.`}</p></div><Button variant="outline" size="sm" disabled={busy || historyLoading || !!deleting} onClick={() => setRefresh(value => value + 1)}>Обновить</Button></header>
    {error && <p role="alert" className="rounded-xl border border-destructive/30 p-3 text-sm text-destructive">{error}</p>}
    {historyLoading && <p role="status" className="text-sm text-muted-foreground">Загрузка истории…</p>}
    {!resultId && <><div className="space-y-2">{history.items.map(item => <div key={item.id} className="flex flex-wrap items-center gap-3 rounded-xl border bg-card p-3"><button disabled={!!deleting || historyLoading} onClick={() => onOpenResult?.(item.id)} className="min-w-0 flex-1 text-left hover:text-primary"><span className="font-medium">{new Date(item.created_at).toLocaleString("ru-RU")}</span><ChevronRight className="ml-2 inline h-4 w-4" /><p className="mt-1 text-xs text-muted-foreground">{item.summary.total_rows} строк · {(item.size / 1048576).toFixed(2)} МиБ · {item.summary.sources.map(source => sourceLabel(source.source)).join(", ")}</p><p className="break-all font-mono text-xs text-muted-foreground">{item.id}</p></button><Button size="sm" variant="outline" disabled={!!deleting || historyLoading} onClick={() => void remove(item)}>{deleting === item.id ? "Удаление…" : "Удалить"}</Button></div>)}</div>{!historyLoading && !error && !history.items.length && <p className="rounded-xl border border-dashed p-6 text-sm text-muted-foreground">Архивов пока нет.</p>}<div className="flex gap-2"><Button size="sm" variant="outline" disabled={historyLoading || !!deleting || offset === 0} onClick={() => setOffset(Math.max(0, offset - 10))}>Назад</Button><Button size="sm" variant="outline" disabled={historyLoading || !!deleting || offset + 10 >= history.total} onClick={() => setOffset(offset + 10)}>Далее</Button></div></>}
    {!historyOnly && resultId && <div className="min-w-0 space-y-4">{selected && <div className="rounded-xl border bg-card p-4"><div className="flex flex-wrap justify-between gap-3"><div><b>{new Date(selected.created_at).toLocaleString("ru-RU")}</b><p className="break-all font-mono text-xs text-muted-foreground">{selected.sha256}</p><p className="text-xs text-muted-foreground">{selected.summary.total_rows} строк · {(selected.size / 1048576).toFixed(2)} МиБ</p><details className="mt-3 text-xs"><summary className="cursor-pointer text-primary">Целостность и полнота источников</summary><p className="my-2 text-muted-foreground">Хеш подтверждает полученные байты, но не авторство или полноту сбора. Пустой источник не означает отсутствие активности.</p>{selected.summary.collection_provenance?.capture_started_utc_claim && <p className="my-2">Начало сбора по часам endpoint (не верифицировано): {selected.summary.collection_provenance.capture_started_utc_claim}</p>}{!!selected.summary.collection_provenance?.requested_sources.length && <div className="my-2 space-y-1">{selected.summary.collection_provenance.requested_sources.map(item => <p key={item.id}><b>{item.id}</b>: {item.status === "missing" ? "источник не получен" : item.status === "empty" ? "источник пуст" : "данные получены"} · {item.observed_rows}/{item.configured_row_limit} строк{item.limit_reached ? " · лимит достигнут: возможна неполнота" : ""}</p>)}</div>}<div className="max-h-64 space-y-2 overflow-auto">{selected.summary.sources.map(item => <div key={item.source} className="rounded border p-2"><b>{sourceLabel(item.source)}</b><p>{item.rows} строк · {item.bytes ?? "размер не зафиксирован"}{item.bytes !== undefined ? " байт" : ""} · {item.status === "empty" ? "пустой источник" : item.status === "present" ? "данные получены" : "legacy: статус не зафиксирован"}</p><p className="mt-1 break-all font-mono">SHA-256: {item.sha256 || "не рассчитан при исходном импорте"}</p><p className="text-muted-foreground">Полнота сбора: не подтверждена</p></div>)}</div></details></div><div className="flex flex-wrap gap-2"><Button size="sm" disabled={busy || !!deleting} onClick={() => void analyze()}>Повторить анализ</Button><Button size="sm" variant="outline" disabled={!analysis || busy} onClick={() => void exportResult("xlsx")}><Download className="mr-1 h-4 w-4" />Excel</Button><Button size="sm" variant="outline" disabled={!analysis || busy} onClick={() => void exportResult("pdf")}>PDF</Button><Button size="sm" variant="outline" disabled={busy || !!deleting} onClick={() => void remove(selected)}>{deleting ? "Удаление…" : "Удалить архив"}</Button></div></div></div>}{busy && <p role="status" className="rounded-xl border p-4 text-sm">Проверка архива и загрузка расследования…</p>}{pipeline && <PipelineBar pipeline={pipeline} analysis={analysis} />}{analysis && selected && <Workspace key={selected.id + analysis.ruleset} analysis={analysis} companyId={companyId} resultId={selected.id} onEvidence={openEvidence} />}</div>}
    {evidence && <EvidenceSheet data={evidence} onPage={next => void openEvidence({ rule_id: "source", title: "", reason: "", source: evidence.source, row_offset: next, row_number: next + 1, classification: "observation" }, next)} onClose={() => setEvidence(null)} />}
  </section>
}

function PipelineBar({ pipeline, analysis }: { pipeline: Pipeline; analysis: Analysis | null }) {
  if (pipeline.status === "completed" && analysis) return <div role="status" className="rounded-xl border bg-card p-3 text-xs text-muted-foreground">Текущий анализ · {Object.values(analysis.rows_reviewed).reduce((sum, count) => sum + count, 0)} проверенных строк · {analysis.matched_rules} срабатываний{pipeline.findings_count !== analysis.matched_rules && <details className="mt-2"><summary className="cursor-pointer">История задания: другой результат анализа</summary><p className="mt-1">Сохранённое задание: {pipeline.rows_processed} строк · {pipeline.findings_count} срабатываний. Это исторический результат, а не счётчик текущего анализа.</p></details>}</div>;
  return <div className="rounded-xl border bg-card p-3"><div className="flex justify-between text-xs"><span><Activity className="mr-1 inline h-4 w-4 text-primary" />{pipeline.stage}</span><b>{pipeline.percent}%</b></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${pipeline.percent}%` }} /></div><p className="mt-2 text-xs text-muted-foreground">{pipeline.message} · {pipeline.rows_processed} строк · {pipeline.findings_count} findings</p>{pipeline.error_message && <p className="mt-2 text-xs text-destructive">{pipeline.error_message}</p>}</div> }
function Metric({ label, value }: { label: string; value: string | number }) { return <div className="rounded-xl border bg-card p-3"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 text-xl font-semibold">{value}</p></div> }
function Workspace({ analysis, companyId, resultId, onEvidence }: { analysis: Analysis; companyId: number; resultId: string; onEvidence: (finding: Finding, offset?: number) => Promise<void> }) { const [tab, setTab] = useState<Tab>("overview"); const [host, setHost] = useState<Record<string, unknown> | null>(null); const [query, setQuery] = useState(""); const [source, setSource] = useState("all"); const [risk, setRisk] = useState("all"); const [scope, setScope] = useState("suspicious"); const [review, setReview] = useState("all"); const [page, setPage] = useState(0); const [active, setActive] = useState<Finding | null>(null); const [manual, setManual] = useState(""); const [question, setQuestion] = useState(""); const [answer, setAnswer] = useState(""); const [publicResearch, setPublicResearch] = useState(false); const [research, setResearch] = useState<{ status: string; sanitized_question: string; disclosure: string; results: { title: string; url: string; host: string }[] } | null>(null); const [asking, setAsking] = useState(false); const [aiError, setAiError] = useState(""); const [exportingAi, setExportingAi] = useState(false); const aiGeneration = useRef(0); const aiBusy = useRef(false); useEffect(() => { aiGeneration.current += 1; aiBusy.current = false; setAnswer(""); setResearch(null); setPublicResearch(false); setAiError(""); setQuestion(""); setAsking(false); return () => { aiGeneration.current += 1 } }, [companyId, resultId]); const [enrichment, setEnrichment] = useState<Record<string, { status: string; disclosure: string; results: { title: string; url: string; host: string }[] }>>({}); const [references, setReferences] = useState<{ id: string; title: string; url: string }[]>([]); useEffect(() => { if (tab === "ai") void api<{ references: { id: string; title: string; url: string }[] }>("/api/threat-hunting/research-references").then(r => setReferences(r.references)).catch(() => setReferences([])) }, [tab]); useEffect(() => { const source = analysis.source_coverage?.find(item => /Host\.json/i.test(item.source))?.source; if (!source) return; void api<Page>(`/api/threat-hunting/results/${resultId}/rows?company_id=${companyId}&source=${encodeURIComponent(source)}&offset=0&limit=1`).then(page => setHost(page.rows[0] || null)).catch(() => setHost(null)) }, [analysis, companyId, resultId]); const [decisions, setDecisions] = useState<Record<string, FindingReview>>({}); async function enrich(ioc: string) { try { const result = await api<{ status: string; disclosure: string; results: { title: string; url: string; host: string }[] }>("/api/threat-hunting/enrichment", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ company_id: companyId, result_id: resultId, ioc, opt_in: true }) }); setEnrichment(current => ({ ...current, [ioc]: result })) } catch (error) { setEnrichment(current => ({ ...current, [ioc]: { status: "error", disclosure: errorMessage(error, "Enrichment недоступен"), results: [] } })) } }
  const identity = (f: Finding) => `${f.rule_id}|${f.source}|${f.row_number}`; const findings = useMemo(() => analysis.findings.map(f => decisions[identity(f)] ? { ...f, review: decisions[identity(f)] } : f), [analysis.findings, decisions]); const sources = [...new Set([...(analysis.source_coverage || []).map(item => item.source), ...findings.map(item => item.source)])]; const filtered = useMemo(() => findings.filter(item => (scope === "all" || suspiciousFinding(item, findings)) && (source === "all" || item.source === source) && (risk === "all" || findingLevel(item) === risk) && (review === "all" || (item.review?.status || "needs_review") === review) && `${item.title} ${item.reason} ${item.rule_id}`.toLowerCase().includes(query.toLowerCase())).sort(compareFindings), [findings, query, source, risk, review, scope]); useEffect(() => { setPage(0); setActive(null) }, [query, source, risk, review, scope]); const rows = filtered.slice(page * 10, page * 10 + 10); useEffect(() => { if (tab === "manual" && !manual) void api<{ content: string }>("/api/threat-hunting/manual").then(result => setManual(result.content)).catch(() => setManual("Manual guide unavailable.")) }, [manual, tab]); async function exportAiReport(format: "md" | "pdf") {
    if (!answer.trim() || asking || exportingAi) return;
    setExportingAi(true); setAiError("");
    try {
      const response = await fetch(`/api/threat-hunting/results/${encodeURIComponent(resultId)}/ai-report?company_id=${companyId}&format=${format}`, { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ answer }) });
      if (!response.ok) { const detail = await response.json().catch(() => ({})); throw new Error(typeof detail.detail === "string" ? detail.detail : "Не удалось выгрузить отчёт"); }
      const blob = await response.blob();
      const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `BroSec-forensic-${resultId}.${format}`; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 30000);
    } catch (error) { setAiError(errorMessage(error, "Ошибка экспорта")); }
    finally { setExportingAi(false); }
  }
  async function ask() { if (aiBusy.current || !question.trim()) return; const generation = aiGeneration.current; aiBusy.current = true; setAsking(true); setAiError(""); try { const result = await api<{ answer: string; research: NonNullable<typeof research> }>("/api/threat-hunting/ai-investigate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ company_id: companyId, hunting_result_id: resultId, message: question, public_research: publicResearch }) }); if (generation !== aiGeneration.current) return; setAnswer(result.answer); setResearch(result.research); setQuestion("") } catch (error) { if (generation === aiGeneration.current) setAiError(errorMessage(error, "AI-ассистент недоступен")) } finally { if (generation === aiGeneration.current) { aiBusy.current = false; setAsking(false) } } } return <div className="space-y-3"><div className="rounded-xl border border-amber-500/30 bg-amber-500/5 p-3 text-sm"><b>Вывод о компрометации не определён.</b> Приоритет эвристики не является вероятностью атаки. Отсутствие находок не доказывает безопасность.{analysis.truncated ? " Список находок ограничен — часть результатов не показана." : ""}<p className="mt-1 text-xs">Не собраны: {analysis.missing_sources.join(", ") || "обязательные источники присутствуют"}; пустые: {analysis.empty_sources.join(", ") || "нет"}; неподдержанных источников: {analysis.unsupported_sources.length}.</p></div><div className="grid grid-cols-2 gap-2 sm:grid-cols-4"><Metric label="Находки" value={findings.length} /><Metric label="Поведенческие сигналы" value={findings.filter(finding => suspiciousFinding(finding, findings)).length} /><Metric label="Приоритет, не % взлома" value={analysis.triage_summary?.max_risk_score ?? "—"} /><Metric label="Проверено" value={findings.filter(finding => finding.review && finding.review.status !== "needs_review").length} /></div><HostContext host={host} analysis={analysis} /><div className="flex gap-1 overflow-x-auto rounded-xl border bg-card p-1" role="tablist">{(["overview", "findings", "activity", "graph", "evidence", "ai", "manual"] as Tab[]).map(value => <button key={value} role="tab" aria-selected={tab === value} onClick={() => setTab(value)} className={`rounded-lg px-3 py-2 text-xs font-medium transition-all duration-300 ${tab === value ? "bg-primary text-primary-foreground shadow-lg shadow-primary/20" : "text-muted-foreground hover:-translate-y-0.5 hover:bg-muted"}`}>{{ overview: "Обзор", findings: "Подозрительные события", activity: "Активность", graph: "Граф связей", evidence: "Evidence", ai: "AI-разбор", manual: "Руководство" }[value]}</button>)}</div>{tab === "overview" && <PriorityOverview findings={findings} onTab={setTab} onEvidence={onEvidence} />}{tab === "activity" && <HuntConsole findings={findings.filter(f => suspiciousFinding(f, findings))} query={query} setQuery={setQuery} source={source} risk={risk} onTab={setTab} onEvidence={onEvidence} />}{tab === "findings" && <div className="grid gap-3 xl:grid-cols-[minmax(0,1fr)_360px]"><div className="rounded-2xl border bg-card"><div className="flex flex-wrap gap-2 border-b p-3"><input aria-label="Поиск по находкам" className="h-9 min-w-40 flex-1 rounded-lg border bg-background px-3 text-sm" placeholder="Поиск…" value={query} onChange={event => setQuery(event.target.value)} /><select aria-label="Область находок" className="h-9 rounded-lg border bg-background px-2 text-sm" value={scope} onChange={event => setScope(event.target.value)}><option value="suspicious">Подозрительные события</option><option value="all">Все наблюдения (включая контекст)</option></select><select aria-label="Источник" className="h-9 rounded-lg border bg-background px-2 text-sm" value={source} onChange={event => { setSource(event.target.value); setPage(0) }}><option value="all">Все источники</option>{sources.map(value => <option key={value} value={value}>{sourceLabel(value)}</option>)}</select><select aria-label="Уровень риска" className="h-9 rounded-lg border bg-background px-2 text-sm" value={risk} onChange={event => { setRisk(event.target.value); setPage(0) }}><option value="all">Все риски</option><option value="critical">Критический</option><option value="high">Высокий</option><option value="medium">Средний</option><option value="low">Низкий</option></select><select aria-label="Статус review" className="h-9 rounded-lg border bg-background px-2 text-sm" value={review} onChange={event => { setReview(event.target.value); setPage(0) }}><option value="all">Все статусы</option><option value="needs_review">Требует проверки</option><option value="confirmed">Подтверждено</option><option value="benign">Доброкачественно</option><option value="insufficient_evidence">Недостаточно evidence</option></select></div><div className="flex items-center justify-between border-b px-3 py-2 text-xs text-muted-foreground"><span>{filtered.length ? page * 10 + 1 : 0}–{Math.min(page * 10 + rows.length, filtered.length)} из {filtered.length} · 10 на странице</span><span className="flex gap-1"><Button size="sm" variant="ghost" disabled={page === 0} onClick={() => setPage(page - 1)}>Назад</Button><Button size="sm" variant="ghost" disabled={(page + 1) * 10 >= filtered.length} onClick={() => setPage(page + 1)}>Далее</Button></span></div>{!filtered.length && <p role="status" className="p-6 text-sm text-muted-foreground">{scope === "suspicious" ? "Подозрительных событий по текущим фильтрам нет. Это не доказывает безопасность хоста. Для проверки контекста выберите «Все наблюдения (включая контекст)»." : "Наблюдений по текущим фильтрам нет. Измените поиск, источник или статус."}</p>}{rows.map(finding => <button key={`${finding.rule_id}-${finding.source}-${finding.row_number}`} onClick={() => setActive(finding)} className={`w-full border-b p-3 text-left hover:bg-muted/50 ${active === finding ? "bg-primary/5" : ""}`}><span className={`mr-2 rounded border px-2 py-1 text-[10px] uppercase ${levelClass(findingLevel(finding))}`}>{findingLevel(finding)}</span><b>{finding.title}</b><span className="float-right text-xs text-muted-foreground">приоритет {finding.risk_score ?? "—"} · {finding.review?.status || "needs_review"}</span><p className="mt-1 text-xs text-muted-foreground">{finding.rule_id} · {sourceLabel(finding.source)} · строка {finding.row_number}</p></button>)}</div><FindingDetail finding={active} companyId={companyId} resultId={resultId} onEvidence={onEvidence} onSaved={saved => { if (active) { setDecisions(current => ({ ...current, [identity(active)]: saved })); setActive({ ...active, review: saved }) } }} /></div>}{tab === "graph" && <GraphView analysis={analysis} onEvidence={onEvidence} />}{tab === "evidence" && <div className="grid gap-2 sm:grid-cols-2">{sources.map(value => <button key={value} onClick={() => { const finding = findings.find(item => item.source === value); void onEvidence(finding || { rule_id: "source", title: value, reason: "", source: value, row_offset: 0, row_number: 1, classification: "observation" }) }} className="rounded-xl border bg-card p-4 text-left hover:border-primary/50"><b>{sourceLabel(value)}</b><p className="mt-1 text-xs text-muted-foreground">{analysis.source_coverage?.find(s => s.source === value)?.rows ?? "—"} строк · {findings.filter(finding => finding.source === value).length} находок · {analysis.source_coverage?.find(s => s.source === value)?.supported ? "поддерживается" : "автопроверки не покрывают источник"}</p></button>)}</div>}{tab === "activity" && <TimelineView analysis={analysis} onEvidence={onEvidence} />}{tab === "evidence" && <div className="mb-4 rounded-xl border p-3"><h4 className="font-medium">Нормализованные IOC</h4><p className="mt-1 text-xs text-muted-foreground">Внешний поиск отправляет только выбранный IP или SHA-256, не сырые события.</p><div className="mt-2 space-y-2">{(analysis.iocs || []).length === 0 ? <p className="text-muted-foreground">Нормализованные внешние IOC не найдены в поддержанных источниках.</p> : null}{(analysis.iocs || []).map(ioc => <div key={ioc.value} className="flex flex-wrap items-center gap-2 rounded border p-2 text-xs"><code>{ioc.type}: {ioc.value}</code><Button size="sm" variant="outline" onClick={() => void enrich(ioc.value)}>Обогатить AI/web</Button>{enrichment[ioc.value] && <span>{enrichment[ioc.value].disclosure}</span>}{enrichment[ioc.value]?.results.map(item => <a key={item.url} href={item.url} target="_blank" rel="noreferrer" className="text-primary underline">{item.host}: {item.title}</a>)}</div>)}</div></div>}{tab === "ai" && <div className="rounded-2xl border bg-card p-4"><h3 className="font-semibold">AI — проверка гипотез по доказательствам</h3><p className="mt-2 text-xs text-muted-foreground">Модель получает ограниченный контекст этого архива. Ответ — гипотезы, не вердикт. По желанию доступны публичные справочные источники по общим вопросам кибербезопасности, не проверка репутации IOC.</p><div className="mt-3 flex flex-wrap gap-2">{["Составь итоговое криминалистическое заключение по доступным данным этого хоста: область и ограничения анализа, установленные факты с source и row_number, хронология с исходными временами и часовыми поясами, признаки исполнения и закрепления, альтернативные объяснения, неподтверждённые гипотезы и необходимые проверки. Не выдумывай связи с другими хостами и не объявляй взлом доказанным по риск-баллу. Пиши связными абзацами без декоративных разделителей.", "Сопоставь признаки компрометации и легитимные объяснения. Цитируй source и row_number.", "Каких данных не хватает для подтверждения или опровержения находок?"].map(prompt => <Button key={prompt} variant="outline" size="sm" onClick={() => setQuestion(prompt)}><Bot aria-hidden="true" />{prompt.startsWith("Составь") ? "Итоговое заключение" : prompt.startsWith("Сопоставь") ? "Проверить гипотезы" : "План досбора"}</Button>)}</div><details className="my-3 text-xs"><summary className="cursor-pointer">Справочные источники — не доказательства атаки</summary>{references.map(ref => <a key={ref.id} href={ref.url} target="_blank" rel="noopener noreferrer" className="mt-2 block text-primary underline">{ref.title}</a>)}</details><label className="my-3 flex items-center gap-2 text-xs"><input type="checkbox" checked={publicResearch} disabled={asking} onChange={event => setPublicResearch(event.target.checked)} />Публичный web-research: только общие понятия, без evidence, секретов и внутренних имён</label>{research && <div role="status" className="my-3 rounded border p-3 text-xs"><b>Публичный поиск: {({ completed: "источники найдены", no_results: "нет разрешённых результатов", unavailable: "провайдер недоступен", not_requested: "не запрошен", not_supported: "общая тема не распознана", response_too_large: "ответ превышает лимит" } as Record<string, string>)[research.status] || research.status}</b>{research.sanitized_question && <p>Отправленный общий вопрос: {research.sanitized_question}</p>}<p>{research.disclosure}</p>{research.results.map(item => <a className="mt-2 block text-primary underline" key={item.url} href={item.url} target="_blank" rel="noopener noreferrer">{item.host}: {item.title}</a>)}</div>}{answer && <div className="my-3 rounded bg-muted/40 p-4"><AssistantAnswer text={answer} /></div>}{aiError && <p role="alert" className="my-3 text-sm text-destructive">{aiError}</p>}{answer && <div className="my-3 flex flex-wrap items-center gap-2"><Button variant="outline" disabled={asking || exportingAi} onClick={() => void exportAiReport("md")}><Download className="size-4" />Заключение MD</Button><Button variant="outline" disabled={asking || exportingAi} onClick={() => void exportAiReport("pdf")}><Download className="size-4" />Заключение PDF</Button><span className="text-xs text-muted-foreground">Вывод ИИ требует проверки аналитиком; источники и ограничения включаются в отчёт.</span></div>}<div className="flex gap-2"><input aria-label="Вопрос AI-ассистенту" className="h-10 min-w-0 flex-1 rounded-lg border bg-background px-3 text-sm" value={question} onChange={event => setQuestion(event.target.value)} onKeyDown={event => { if (event.key === "Enter") void ask() }} placeholder="Что проверить в этих findings?" /><Button disabled={asking || !question.trim()} onClick={() => void ask()}><Bot className="mr-1 h-4 w-4" />Спросить</Button></div></div>}{tab === "manual" && <pre className="max-h-[520px] overflow-auto whitespace-pre-wrap rounded-2xl border bg-card p-4 text-sm leading-6 text-muted-foreground">{manual || "Загрузка руководства…"}</pre>}</div> }
function HostContext({ host, analysis }: { host: Record<string, unknown> | null; analysis: Analysis }) { const hostname = String(host?.Hostname || host?.Fqdn || "Хост не определён"); const ip = String(host?.IPAddress || host?.IP || host?.IPv4 || "IP не собран"); const os = String(host?.Platform || host?.OS || "ОС не определена"); return <div className="rounded-2xl border bg-gradient-to-r from-card via-card to-primary/5 p-4 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-3"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-primary/10 text-lg">⌂</div><div><p className="text-[10px] font-mono uppercase tracking-[0.18em] text-muted-foreground">Исследуемый хост</p><h3 className="text-xl font-semibold">{hostname}</h3><p className="text-xs text-muted-foreground">{os} · {ip}</p></div></div><div className="flex flex-wrap gap-2 text-xs"><span className="rounded-full border bg-background px-3 py-1">Контекст из импортированного архива</span><span className="rounded-full border bg-background px-3 py-1">{analysis.source_coverage?.find(source => /(?:^|\/)Processes\.json$/i.test(source.source))?.rows ?? "—"} строк процессов</span><span className="rounded-full border bg-background px-3 py-1">{analysis.source_coverage?.find(source => /(?:^|\/)Network\.json$/i.test(source.source))?.rows ?? "—"} сетевых строк</span></div></div></div> }
function PriorityOverview({ findings, onTab, onEvidence }: { findings: Finding[]; onTab: (tab: Tab) => void; onEvidence: (finding: Finding, offset?: number) => Promise<void> }) { const candidates = findings.filter(f => suspiciousFinding(f, findings)).sort(compareFindings); const priority = candidates.slice(0, 6); return <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px]"><div className="rounded-2xl border bg-card"><div className="flex items-center justify-between border-b p-4"><div><h3 className="font-semibold">Поведенческие сигналы</h3><p className="text-xs text-muted-foreground">Команды, обфускация и связанные процессы. Требуется проверка; это не подтверждённый инцидент.</p></div><button className="text-xs text-primary hover:underline" onClick={() => onTab("findings")}>Все находки</button></div>{priority.length ? priority.map(finding => <button key={`${finding.rule_id}-${finding.source}-${finding.row_number}`} onClick={() => void onEvidence(finding)} className="flex w-full items-center justify-between gap-3 border-b p-4 text-left transition hover:bg-primary/5"><span className={`rounded px-2 py-1 text-[10px] uppercase ${levelClass(findingLevel(finding))}`}>{findingLevel(finding)}</span><span className="min-w-0 flex-1"><span className="block text-sm font-medium">{finding.title}</span><span className="mt-1 block text-xs text-muted-foreground">{finding.reason}</span></span><span className="text-xs text-muted-foreground">строка {finding.row_number}</span></button>) : <p className="p-6 text-sm text-muted-foreground">В показанном анализе нет событий, прошедших отбор подозрительных признаков. Это не доказывает безопасность хоста. Контекст доступен через фильтр «Все наблюдения».</p>}</div><div className="space-y-3"><button onClick={() => onTab("activity")} className="w-full rounded-2xl border bg-card p-4 text-left transition hover:border-primary/50"><p className="text-xs text-muted-foreground">Активность</p><p className="mt-1 text-2xl font-semibold">{findings.length}</p><p className="text-xs text-muted-foreground">находок из анализа · открыть timeline</p></button><button onClick={() => onTab("graph")} className="w-full rounded-2xl border bg-card p-4 text-left transition hover:border-primary/50"><p className="text-xs text-muted-foreground">Связи</p><p className="mt-1 text-2xl font-semibold">{findings.filter(f => f.rule_id.startsWith("correlation.")).length}</p><p className="text-xs text-muted-foreground">корреляций в process graph</p></button></div></div> }

function HuntConsole({ findings, query, setQuery, source, risk, onTab, onEvidence }: { findings: Finding[]; query: string; setQuery: (value: string) => void; source: string; risk: string; onTab: (tab: Tab) => void; onEvidence: (finding: Finding, offset?: number) => Promise<void> }) { const [mitre, setMitre] = useState<string[]>([]); const [showQuery, setShowQuery] = useState(false); const [expanded, setExpanded] = useState<string | null>(null); const tactics = [...new Set(findings.map(item => item.rule_id.split('.')[0]))]; const filtered = findings.filter(item => (source === "all" || item.source === source) && (risk === "all" || findingLevel(item) === risk) && (!mitre.length || mitre.includes(item.rule_id.split('.')[0])) && (!query || `${item.title} ${item.reason} ${item.rule_id}`.toLowerCase().includes(query.toLowerCase()))); const buckets = [...new Set(filtered.map(item => item.rule_id.split(".")[0]))].map(label => ({ label, value: filtered.filter(item => item.rule_id.split(".")[0] === label).length })); const max = Math.max(...buckets.map(item => item.value), 1); return <section className="overflow-hidden rounded-2xl border bg-card shadow-sm"><div className="flex flex-wrap items-center gap-2 border-b bg-muted/20 p-3"><div className="flex min-w-[280px] flex-1 items-center gap-2 rounded-lg border bg-background px-3 py-2"><Search className="h-4 w-4 text-muted-foreground" /><input aria-label="Query builder" className="min-w-0 flex-1 bg-transparent text-sm outline-none" value={query} onChange={event => setQuery(event.target.value)} placeholder="process.name == powershell.exe  ·  remote.ip == 8.8.8.8" /><button aria-label="Параметры запроса" onClick={() => setShowQuery(!showQuery)} className="rounded p-1 hover:bg-muted"><SlidersHorizontal className="h-4 w-4" /></button>{query && <button aria-label="Очистить запрос" onClick={() => setQuery("")}><X className="h-4 w-4 text-muted-foreground" /></button>}</div><select aria-label="MITRE tactic" multiple className="h-10 max-w-44 rounded-lg border bg-background px-2 text-xs" value={mitre} onChange={event => setMitre([...event.target.selectedOptions].map(option => option.value))}>{tactics.map(item => <option key={item} value={item}>{item}</option>)}</select><button onClick={() => onTab("findings")} className="rounded-lg bg-primary px-3 py-2 text-xs font-medium text-primary-foreground">Hunt {filtered.length}</button></div>{showQuery && <div className="border-b bg-primary/5 px-4 py-3 text-xs"><p className="font-medium">Конструктор гипотез</p><div className="mt-2 flex flex-wrap gap-2">{["process.name == powershell.exe", "network.remote_ip == public", "persistence.path contains AppData", "parent.name == svchost.exe"].map(item => <button key={item} onClick={() => setQuery(item)} className="rounded-full border bg-card px-3 py-1 hover:border-primary">{item}</button>)}</div></div>}<div className="grid gap-0 lg:grid-cols-[minmax(0,1fr)_260px]"><div className="min-w-0 p-4"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Находки по группам правил</p><p className="text-sm">Реальные количества находок в выбранном срезе, не временная шкала</p></div><button onClick={() => onTab("activity")} className="text-xs text-primary hover:underline">Открыть timeline</button></div><div className="mt-4 flex h-24 items-end gap-1">{buckets.map(bucket => <button key={bucket.label} title={`${bucket.label}: ${bucket.value}`} onClick={() => setQuery(bucket.label)} className="group flex flex-1 flex-col justify-end"><span className="mb-1 text-[9px] text-muted-foreground opacity-0 group-hover:opacity-100">{bucket.value}</span><span className="min-h-1 rounded-t bg-gradient-to-t from-primary/40 to-primary transition-all duration-500 group-hover:from-cyan-400 group-hover:to-primary" style={{ height: `${Math.max(4, bucket.value / max * 76)}px` }} /></button>)}</div><div className="mt-1 flex flex-wrap justify-between gap-2 text-[9px] text-muted-foreground">{buckets.map(bucket => <span key={bucket.label}>{bucket.label}: {bucket.value}</span>)}</div></div><div className="border-t p-4 lg:border-l lg:border-t-0"><p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Hypotheses</p><div className="mt-2 space-y-2">{["process", "network", "persistence"].map(item => <button key={item} onClick={() => setQuery(item)} className="flex w-full items-center justify-between rounded-lg border px-3 py-2 text-left text-xs hover:border-primary"><span>{item}</span><b>{findings.filter(f => f.rule_id.startsWith(item)).length}</b></button>)}</div></div></div><div className="border-t"><div className="flex items-center justify-between px-4 py-2 text-xs text-muted-foreground"><span>Evidence preview · {filtered.length} rows</span><span>Клик по строке откроет inspector</span></div>{filtered.slice(0, 8).map(item => <div key={`${item.rule_id}-${item.source}-${item.row_number}`} className="group border-t px-4 py-2 text-xs hover:bg-primary/5"><button className="grid w-full grid-cols-[70px_minmax(0,1fr)_100px_24px] items-center gap-2 text-left" onClick={() => setExpanded(expanded === `${item.rule_id}-${item.row_number}` ? null : `${item.rule_id}-${item.row_number}`)}><span className={`w-fit rounded px-1.5 py-0.5 text-[10px] uppercase ${levelClass(findingLevel(item))}`}>{findingLevel(item)}</span><span className="truncate font-medium">{item.title}</span><span className="truncate text-muted-foreground">{sourceLabel(item.source)}:{item.row_number}</span><Maximize2 className="h-3 w-3 text-muted-foreground" /></button>{expanded === `${item.rule_id}-${item.row_number}` && <div className="mt-2 grid gap-2 rounded-lg bg-muted/30 p-3 md:grid-cols-2"><div><b>Rule</b><p className="font-mono text-muted-foreground">{item.rule_id}</p></div><div><b>Evidence</b><p className="font-mono text-muted-foreground">{item.source}:{item.row_number}</p></div><pre className="max-h-32 overflow-auto whitespace-pre-wrap break-all rounded bg-background p-2 text-[10px] md:col-span-2">{JSON.stringify(item.evidence || {}, null, 2)}</pre><button onClick={() => void onEvidence(item)} className="text-left text-primary underline">Открыть полный evidence inspector</button></div>}</div>)}</div></section> }

function TimelineView({ analysis, onEvidence }: { analysis: Analysis; onEvidence: (finding: Finding, offset?: number) => Promise<void> }) { const [query, setQuery] = useState(""); const [category, setCategory] = useState("all"); const allEvents = analysis.triage_summary?.timeline || []; const categories = [...new Set(allEvents.map(event => event.category || "Other"))]; const events=allEvents.filter(event => (category === "all" || (event.category || "Other") === category) && `${event.timestamp} ${event.source}`.toLowerCase().includes(query.toLowerCase())); return <div className="rounded-2xl border bg-card p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><h3 className="font-semibold">Хронология исходных событий</h3><p className="mt-1 text-xs text-muted-foreground">Только записи с распознанным временем; без timezone трактуется как UTC. {analysis.triage_summary?.timeline_truncated ? "Показан ограниченный срез." : ""}</p></div><div className="flex gap-2"><select aria-label="Категория timeline" className="rounded border bg-background p-2 text-xs" value={category} onChange={event => setCategory(event.target.value)}><option value="all">Все категории</option>{categories.map(item => <option key={item} value={item}>{item}</option>)}</select><input aria-label="Фильтр timeline" className="rounded border bg-background p-2 text-xs" placeholder="IP, источник, время" value={query} onChange={event => setQuery(event.target.value)} /></div></div><div className="mt-3 border-l-2 border-primary/30 pl-4">{events.slice(0, 500).map((event, index) => <button key={`${event.timestamp}-${index}`} onClick={() => void onEvidence({ rule_id: "timeline", title: "", reason: "", source: event.source, row_number: event.row_number, row_offset: event.row_number - 1, classification: "observation" })} className="relative mt-3 block w-full text-left text-sm hover:underline"><span className="absolute -left-[1.35rem] top-1 h-2 w-2 rounded-full bg-primary" /><Clock3 className="mr-2 inline h-4 w-4" />{event.timestamp} · {event.category || "Other"} · {sourceLabel(event.source)} · строка {event.row_number}</button>)}</div><p className="mt-3 text-xs text-muted-foreground">Показано {Math.min(events.length,500)} из {events.length} совпадений.</p></div> }

function GraphView({ analysis, onEvidence }: { analysis: Analysis; onEvidence: (finding: Finding, offset?: number) => Promise<void> }) {
  return <HuntingEvidenceGraph graph={analysis.graph} onEvidence={ref => { void onEvidence({ rule_id: "graph", title: "Связанный объект", reason: "Исходная строка графа связей", source: ref.source, row_number: ref.row_number, row_offset: Math.max(0, ref.row_number - 1), classification: "observation" }) }} />
}

function FindingDetail({ finding, companyId, resultId, onEvidence, onSaved }: { finding: Finding | null; companyId: number; resultId: string; onEvidence: (finding: Finding, offset?: number) => Promise<void>; onSaved: (review: FindingReview) => void }) { const [note, setNote] = useState(""); const [status, setStatus] = useState<FindingReview["status"]>("needs_review"); const [saving, setSaving] = useState(false); useEffect(() => { setNote(finding?.review?.note || ""); setStatus(finding?.review?.status || "needs_review") }, [finding]); if (!finding) return <div className="flex min-h-[420px] items-center justify-center rounded-2xl border border-dashed bg-card/50 p-6 text-sm text-muted-foreground">Выберите finding, чтобы открыть детали</div>; async function save() { if (note.trim().length < 3) return; setSaving(true); try { const saved = await api<FindingReview>("/api/threat-hunting/findings/review", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ company_id: companyId, result_id: resultId, finding: { ...finding }, status, note: note.trim() }) }); onSaved(saved); setNote("") } catch (error) { window.alert(errorMessage(error, "Review не сохранён")) } finally { setSaving(false) } } return <div className="rounded-2xl border bg-card p-4 shadow-sm"><span className={`rounded border px-2 py-1 text-xs uppercase ${levelClass(findingLevel(finding))}`}>{findingLevel(finding)}</span><h3 className="mt-3 text-lg font-semibold">{finding.title}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{finding.reason}</p><div className="mt-4 grid grid-cols-2 gap-2"><Metric label="Сила эвристики, не % взлома" value={finding.confidence ?? "—"} /><Metric label="Строка" value={finding.row_number} /></div><div className="mt-3 space-y-3 text-xs"><div><b>Легитимные объяснения</b>{(finding.benign_explanations || []).map(text => <p key={text} className="mt-1 text-muted-foreground">{text}</p>)}</div><div><b>Пробелы доказательств</b>{(finding.data_gaps || []).map(text => <p key={text} className="mt-1 text-muted-foreground">{text}</p>)}</div><div><b>Следующие проверки</b>{(finding.recommended_checks || []).map(text => <p key={text} className="mt-1">• {text}</p>)}</div><div><b>Связанные доказательства</b>{(finding.evidence_refs || []).map((ref, i) => <button key={i} className="mt-1 block text-primary underline break-all" onClick={() => void onEvidence({ ...finding, source: ref.source, row_number: ref.row_number, row_offset: ref.row_number - 1 })}>{sourceLabel(ref.source)} : {ref.row_number} · {ref.relation}</button>)}</div></div><Button className="mt-3 w-full" variant="outline" onClick={() => void onEvidence(finding)}><FileSearch className="mr-2 h-4 w-4" />Открыть evidence</Button><select className="mt-4 h-9 w-full rounded border bg-background px-2 text-sm" value={status} onChange={event => setStatus(event.target.value as FindingReview["status"])}><option value="needs_review">Требует проверки</option><option value="confirmed">Подтверждено</option><option value="benign">Доброкачественно</option><option value="insufficient_evidence">Недостаточно evidence</option></select><textarea className="mt-2 min-h-20 w-full rounded border bg-background p-2 text-sm" value={note} onChange={event => setNote(event.target.value)} placeholder="Заметка обязательна" maxLength={4000} /><Button className="mt-2 w-full" disabled={saving || note.trim().length < 3} onClick={() => void save()}>{saving ? "Сохранение…" : "Сохранить решение"}</Button>{finding.review && <p className="mt-2 text-xs text-muted-foreground">Сохранено: {finding.review.status} · {finding.review.note}</p>}</div> }
function EvidenceSheet({ data, onClose, onPage }: { onPage: (offset: number) => void; data: { page: Page; source: string; offset: number }; onClose: () => void }) { return <Sheet open onOpenChange={open => { if (!open) onClose() }}><SheetContent side="right" className="w-full overflow-y-auto sm:max-w-2xl"><SheetHeader><SheetTitle>Evidence viewer</SheetTitle><SheetDescription className="break-all font-mono">{sourceLabel(data.source)} · {data.page.offset + 1}–{Math.min(data.page.offset + data.page.rows.length, data.page.total)} из {data.page.total}</SheetDescription></SheetHeader><div className="space-y-2 p-4">{data.page.rows.map((row, index) => <details key={index} open={data.page.rows.length === 1} className="rounded-lg border p-3"><summary className="cursor-pointer text-xs font-medium">Строка {data.page.offset + index + 1}</summary><pre className="mt-3 max-h-[32rem] overflow-auto whitespace-pre-wrap break-all rounded bg-muted/40 p-3 text-xs">{JSON.stringify(row, null, 2)}</pre></details>)}</div><div className="flex gap-2 p-4"><Button className="flex-1" variant="outline" disabled={data.page.offset === 0} onClick={() => onPage(Math.max(0, data.page.offset - 25))}>Предыдущие</Button><Button className="flex-1" variant="outline" disabled={data.page.offset + 25 >= data.page.total} onClick={() => onPage(data.page.offset + 25)}>Следующие</Button></div></SheetContent></Sheet> }
